(x, y, t) => {
  let gx = x % 24, gy = y % 24;
  let grid = ((gx === 0 | gy === 0) ? 1 : 0);
  let dot = (gx === 12 & gy === 12) ? 1 : 0;

  // Multiple layered sine waves
  let v1 = Math.sin(x * 0.02 + t * 1.3) * Math.cos(y * 0.03 - t * 0.7);
  let v2 = Math.sin(Math.sqrt((x-240)**2 + (y-120)**2) * 0.05 - t * 2);
  let v3 = Math.sin((x ^ y) * 0.01 + t);
  let v4 = Math.cos(x * 0.01 * Math.sin(t * 0.5) + y * 0.01 * Math.cos(t * 0.3));

  let plasma = (v1 + v2 + v3 + v4) * 0.25;

  // Panel regions
  let panel = (y < 20) | (y > 220) | (x < 16) | (x > 464);
  let subpanel = (y > 20 & y < 40 & x > 200 & x < 460);

  // Color mapping
  let r = Math.sin(plasma * Math.PI + t) * 127 + 128;
  let g = Math.cos(plasma * Math.PI * 1.3 - t * 0.5) * 127 + 128;
  let b = Math.sin(plasma * Math.PI * 0.7 + t * 0.8) * 80 + 60;

  // Apply grid and dots
  r = r * (1 - grid * 0.7) + grid * 40;
  g = g * (1 - grid * 0.7) + grid * 80;
  b = b * (1 - grid * 0.7) + grid * 120;

  r = r * (1 - dot * 0.5) + dot * 200;
  g = g * (1 - dot * 0.5) + dot * 220;
  b = b * (1 - dot * 0.5) + dot * 255;

  // Apply panel darkening
  r = r * (1 - panel * 0.6) + panel * 15;
  g = g * (1 - panel * 0.6) + panel * 25;
  b = b * (1 - panel * 0.6) + panel * 45;

  // Subpanel highlight
  r = r * (1 - subpanel * 0.3) + subpanel * 100;
  g = g * (1 - subpanel * 0.3) + subpanel * 150;
  b = b * (1 - subpanel * 0.3) + subpanel * 200;

  return [
    r & 255,
    g & 255,
    b & 255
  ];
}
